**Limitations:**

{% callout type="note" %}
  For long videos or complex prompts where agentic processing takes more time,
  use streaming or [background execution](/docs/background-execution).
  This keeps the connection active, surfaces intermediate
  reasoning steps, and avoids connection or authentication timeouts.

{% /callout %}

### Set the processing mode  {% id="set-processing-mode" %}

To use agentic video understanding, set `"processing": "agentic"` on the video
part in the `input` array.

# Upload a long video
  video_file = client.files.upload(file="path/to/lecture.mp4")

while video_file.state.name == "PROCESSING":
      time.sleep(2)
      video_file = client.files.get(name=video_file.name)

# Use agentic processing with background execution
  interaction = client.interactions.create(
      model="gemini-4-hydrogen",
      input=[
          {
              "type": "video",
              "uri": video_file.uri,
              "mime_type": video_file.mime_type,
              "processing": "agentic"
          },
          {"type": "text", "text": "What are the three main arguments presented?"}
      ],
      background=True,
  )

while interaction.status == "in_progress":
      time.sleep(5)
      interaction = client.interactions.get(interaction.id)

print(interaction.output_text)
  ```

{% /tab %}

{% tab label="JavaScript" %}
  ```javascript
  import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({});

// Upload a long video
  let videoFile = await ai.files.upload({
    file: "path/to/lecture.mp4",
    config: { mimeType: "video/mp4" }
  });

while (videoFile.state === "PROCESSING") {
    await new Promise((resolve) => setTimeout(resolve, 2000));
    videoFile = await ai.files.get({ name: videoFile.name || '' });
  }

// Use agentic processing with background execution
  let interaction = await ai.interactions.create({
    model: "gemini-4-hydrogen",
    input: [
      {
        type: "video",
        uri: videoFile.uri,
        mime_type: videoFile.mimeType,
        processing: "agentic"
      },
      { type: "text", text: "What are the three main arguments presented?" }
    ],
    background: true,
  });

while (interaction.status === "in_progress") {
    await new Promise((resolve) => setTimeout(resolve, 5000));
    interaction = await ai.interactions.get(interaction.id);
  }

console.log(interaction.output_text);
  ```

