      model="gemini-4-hydrogen",
      input=[
          {
              "type": "video",
              "uri": video_file.uri,
              "mime_type": video_file.mime_type,
              "processing": {
                  "type": "static",
                  "start_offset": "1200s",
                  "end_offset": "1500s",
              },
          },
          {"type": "text", "text": "Summarize this section of the video."},
      ],
  )
  print(interaction.output_text)
