                  "type": "string",
                  "enum": ["daylight", "cool", "warm"],
                  "description": "Color temperature",
              },
          },
          "required": ["brightness", "color_temp"],
      },
  }

def set_light_values(brightness: int, color_temp: str) -> dict:
